import React, { useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { toast } from "react-toastify";
import { RoutesStrings } from "../constant/constant";
import Messeges from "../constant/Messeges";
import { resetPassword } from "../store/slices/authSlice";
import { useAppDispatch, useAppSelector } from "../store/store";
import { formErrorT } from "../types";

const ResetPassword: React.FC = () => {
  const { token } = useParams<{ token: string }>();
  const [password, setPassword] = useState<string>("");
  const [confirmPassword, setConfirmPassword] = useState<string>("");
  const [showPassword, setShowPassword] = useState<boolean>(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState<boolean>(false);
  const [formError, setFormError] = useState<formErrorT>({});

  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const { loading } = useAppSelector((state) => state.auth);

  const validateInput = () => {
    let errors: formErrorT = {};
    let valid = true;

    if (!password) {
      errors.password = Messeges.v_password;
      valid = false;
    }
    else if (password.length < 6) {
      errors.password = Messeges.v_password1;
      valid = false;
    }
    else {
      if (confirmPassword.length < 6) {
        errors.confirmPassword = Messeges.v_password1;
        valid = false;
      }

      if (confirmPassword !== password) {
        errors.confirmPassword = Messeges.v_password2;
        valid = false;
      }
    }

    if (!token) {
      errors.token = Messeges.v_token_missing;
      valid = false;
    }

    setFormError(errors);
    return valid;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validateInput()) {
      dispatch(resetPassword({ token: token || "", password: password })).
        then((res: any) => {
          if (!res?.error) {
            navigate(RoutesStrings.login)
          }
          else {
            toast.error(Messeges.s_wentwrong);
          }
        });
    }
  };

  return (
    <div className="container">
      <div className="row justify-content-center">
        <div className="col-md-6 col-lg-5">
          <div className="card shadow-sm mt-5">
            <div className="card-body p-4">
              <h3 className="card-title text-center mb-4">Set a new password</h3>

              <form onSubmit={handleSubmit}>
                <div className="mb-3">
                  <label htmlFor="password" className="form-label">
                    New password
                  </label>
                  <div className="input-group">
                    <input
                      type={showPassword ? "text" : "password"}
                      id="password"
                      className="form-control"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      placeholder="At least 6 characters"
                    />
                    <button
                      className="btn btn-outline-primary"
                      type="button"
                      id="togglePassword"
                      onClick={() => setShowPassword(!showPassword)}>
                      <i className={`bi ${showPassword ? "bi-eye-slash" : "bi-eye"}`}></i>
                    </button>
                  </div>
                  <div className="text-danger">
                    {formError?.password}
                  </div>
                </div>

                <div className="mb-3">
                  <label htmlFor="confirmPassword" className="form-label">
                    Confirm new password
                  </label>
                  <div className="input-group">
                    <input
                      type={showConfirmPassword ? "text" : "password"}
                      id="confirmPassword"
                      className="form-control"
                      value={confirmPassword}
                      onChange={(e) => setConfirmPassword(e.target.value)}
                      placeholder="Repeat your new password"
                    />
                    <button
                      className="btn btn-outline-primary"
                      type="button"
                      id="togglePassword"
                      onClick={() => setShowConfirmPassword(!showConfirmPassword)}>
                      <i className={`bi ${showConfirmPassword ? "bi-eye-slash" : "bi-eye"}`}></i>
                    </button>
                  </div>
                  <div className="text-danger">
                    {formError?.confirmPassword}
                  </div>
                </div>

                <button type="submit" className="btn btn-primary w-100" disabled={loading}>
                  {loading ? "Resetting..." : "Reset password"}
                </button>
              </form>

              <p className="text-center mt-3 mb-0">
                <Link to={RoutesStrings.login}>Back to login</Link>
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ResetPassword;
