import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { toast } from "react-toastify";
import { RoutesStrings } from "../constant/constant";
import Messeges from "../constant/Messeges";
import { forgotPassword } from "../store/slices/authSlice";
import { useAppDispatch, useAppSelector } from "../store/store";
import { formErrorT } from "../types";
import { emailValidate } from "../utility";

const ForgotPassword: React.FC = () => {
  const [email, setEmail] = useState<string>("");
  const [formError, setFormError] = useState<formErrorT>({});

  const [page, setPage] = useState<number>(0);
  const [timer, setTimer] = useState<number>(30);
  const [timerKey, setTimerKey] = useState<number>(0);
  const [canResend, setCanResend] = useState<boolean>(false);

  const dispatch = useAppDispatch();
  const { loading } = useAppSelector((state) => state.auth);

  useEffect(() => {
    if (page != 1) return;

    setTimer(30);
    setCanResend(false);

    const interval = setInterval(() => {
      setTimer((prev) => {
        if (prev <= 1) {
          clearInterval(interval);
          setCanResend(true);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [page, timerKey]);

  const validateInput = () => {
    let errors: formErrorT = {};
    let valid = true;

    if (!email.trim()) {
      errors.email = Messeges.v_email;
      valid = false;
    } else if (!emailValidate(email)) {
      errors.email = Messeges.v_email1;
      valid = false;
    }
    setFormError(errors);

    return valid;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateInput()) return;
    dispatch(forgotPassword({ email }))
      .then((res: any) => {
        if (!res.error) {
          setPage(1);
        }
        else {
          toast.error(res.payload || Messeges.s_wentwrong);
        }
      });
  };

  const handleResendOTP = async () => {
    if (!canResend) return;

    await dispatch(forgotPassword({ email }))
      .then((res: any) => {
        if (!res.error) {
          toast.success(res.payload)
        }
        else {
          toast.error(res.payload || Messeges.s_wentwrong);
        }
      });

    setTimerKey((prev) => prev + 1);
  };

  const handleVerifyOTP = (e: React.MouseEvent<HTMLButtonElement>) => {
    e.preventDefault();
    setPage(0);
  }

  return (
    <div className="container">
      <div className="row justify-content-center">
        <div className="col-md-6 col-lg-5">
          <div className="card shadow-sm mt-5">
            <div className="card-body p-4">
              <h3 className="card-title text-center mb-3">Forgot your password?</h3>


              {page == 0 &&
                <React.Fragment>
                  <p className="text-muted text-center mb-4">
                    Enter your email and we'll send you a link to reset it.
                  </p>

                  <form onSubmit={handleSubmit}>
                    <div className="mb-3">
                      <label htmlFor="email" className="form-label">
                        Email address
                      </label>
                      <input
                        type="email"
                        id="email"
                        className="form-control"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        placeholder="you@example.com"
                      />
                      <div className="text-danger">
                        {formError?.email}
                      </div>
                    </div>

                    <button type="submit" className="btn btn-primary w-100" disabled={loading}>
                      {loading ? "Sending..." : "Send reset link"}
                    </button>
                  </form>
                </React.Fragment>
              }
              {page == 1 &&
                <React.Fragment>
                  <p className="text-muted text-center mb-3">
                    Please check the email address you entered. A password reset link has been sent to that email address.
                  </p>

                  <div className="text-center mb-3">
                    <p className="text-center d-block mb-3">
                      {canResend ? (
                        <a tabIndex={-1} role="button" className="text-decoration-none"
                          onClick={handleResendOTP}>
                          Resend Link
                        </a>) :
                        (
                          <p className="text-muted">
                            Resend Link in {timer}s
                          </p>
                        )}
                    </p>

                    <button type="button" className="btn btn-primary w-100" onClick={handleVerifyOTP}>
                      Back
                    </button>
                  </div>

                </React.Fragment>}

              <p className="text-center mt-3 mb-0">
                <Link to={RoutesStrings.login}>Back to login</Link>
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ForgotPassword;
