import DropIn from "braintree-web-drop-in-react";
import React, { useEffect, useState } from "react";
import { toast } from "react-toastify";
import { PlanTypeEnum } from "../constant/constant";
import Messeges from "../constant/Messeges";
import { updateUserPlan } from "../store/slices/authSlice";
import {
  cancelSubscription,
  checkout,
  clearClientToken,
  fetchClientToken,
  fetchMySubscription,
  fetchPlans
} from "../store/slices/subscriptionSlice";
import { useAppDispatch, useAppSelector } from "../store/store";
import { PlanId } from "../types";
import { PLAN_ICONS } from "../utils/planIcons";

interface SubscriptionModalProps {
  show: boolean;
  onClose: () => void;
}

const SubscriptionModal: React.FC<SubscriptionModalProps> = ({ show, onClose }) => {
  const dispatch = useAppDispatch();
  const { plans, plansLoading, clientToken, clientTokenLoading, checkoutLoading, subscribedPlan,
    cancelSubscriptionLoading
  } =
    useAppSelector((state) => state.subscription);
  const { user } = useAppSelector((state) => state.auth);

  const [selectedPlan, setSelectedPlan] = useState<PlanId | null>(null);
  const [dropinInstance, setDropinInstance] = useState<any>(null);

  useEffect(() => {
    if (show) {
      dispatch(fetchPlans()).then((res: any) => {
        if (!res.error) {
          toast.error(res.error);
        }
      });
      setSelectedPlan(null);
      dispatch(clearClientToken());
      dispatch(fetchMySubscription());
    }
  }, [show, dispatch]);

  if (!show) return null;

  const handleCancelPlan = (planId: PlanId) => {
    if (planId === user.plan) {
      if (window.confirm(Messeges.c_cancel_subscription)) {
        dispatch(cancelSubscription({ subscriptionId: subscribedPlan?.braintreeSubscriptionId }))
          .then((res: any) => {
            if (!res.error) {
              dispatch(updateUserPlan("Free"));
              toast.success(Messeges.m_plancanceled);
              onClose();
              dispatch(fetchMySubscription());
            }
          })
      }
      return
    }
  }

  const handleChoosePlan = (planId: PlanId) => {
    if (planId !== PlanTypeEnum.Free) {
      dispatch(fetchClientToken());
    }
    setSelectedPlan(planId);
  };

  const handlePay = async () => {
    if (!dropinInstance || !selectedPlan) return;
    try {
      const payload = await dropinInstance.requestPaymentMethod();
      console.log(payload)
      const res: any = await dispatch(
        checkout({ planId: selectedPlan, paymentMethodNonce: payload.nonce })
      );
      if (!res.error) {
        dispatch(updateUserPlan(selectedPlan));
        toast.success(res.payload?.message || Messeges.m_upgrade_successful);
        onClose();
      } else {
        toast.error(res.payload || Messeges.m_payment_failed);
      }
    } catch (err: any) {
      toast.error(err?.message || Messeges.m_card_detail);
    }
  };

  const selectedPlanDef = plans.find((p) => p.planid === selectedPlan);

  return (
    <div
      className="modal fade show d-block"
      tabIndex={-1}
      style={{ backgroundColor: "rgba(15, 23, 42, 0.6)" }}
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="modal-dialog modal-dialog-centered modal-xl">
        <div className="modal-content border-0 shadow-lg" style={{ borderRadius: 16 }}>
          <div className="modal-header border-0 pb-0">
            <div>
              <h4 className="modal-title fw-bold mb-1">
                {selectedPlan ? "Complete your upgrade" : "Choose your plan"}
              </h4>
              <p className="text-muted mb-0 small">
                {selectedPlan
                  ? "Secure payment powered by Braintree"
                  : "Upgrade any time. Cancel any time. No hidden fees."}
              </p>
            </div>
            <button type="button" className="btn-close" onClick={onClose}></button>
          </div>

          <div className="modal-body pt-3">

            {!selectedPlan && (
              <div className="row g-4 py-2">
                {plansLoading && plans.length === 0 && (
                  <div className="text-center py-5">
                    <div className="spinner-border text-primary" role="status" />
                  </div>
                )}
                {plans.map((plan) => {
                  const isCurrent = user?.plan === plan.planid;
                  const isPopular = plan.planid === PlanTypeEnum.standard_month;
                  return (
                    <div className="col-md-4" key={plan.planid}>
                      <div
                        className={`card h-100 position-relative ${isPopular ? "border-primary shadow" : "border"
                          }`}
                        style={{ borderRadius: 14, borderWidth: isPopular ? 2 : 1 }}
                      >
                        {isPopular && (
                          <span className="badge bg-primary position-absolute top-0 start-50 translate-middle px-3 py-2 rounded-pill">
                            Most Popular
                          </span>
                        )}
                        <div className="card-body d-flex flex-column p-4 pt-5">
                          <div
                            className="d-inline-flex align-items-center justify-content-center rounded-circle bg-primary bg-opacity-10 text-primary mb-3"
                            style={{ width: 48, height: 48 }}
                          >
                            <i className={`bi ${PLAN_ICONS[plan.planid]} fs-4`}></i>
                          </div>
                          <h5 className="fw-bold">{plan.name}</h5>
                          <div className="mb-3">
                            <span className="display-6 fw-bold">${plan.price}</span>
                            <span className="text-muted">/month</span>
                          </div>
                          <ul className="list-unstyled flex-grow-1 mb-4">
                            {plan.features?.map((feature) => (
                              <li key={feature} className="mb-2 d-flex align-items-start">
                                <i className="bi bi-check-circle-fill text-success me-2 mt-0"></i>
                                <span className="small">{feature}</span>
                              </li>
                            ))}
                          </ul>
                          {isCurrent ?
                            <button
                              className={`btn w-100 ${"btn-outline-danger"}`}
                              onClick={() => handleCancelPlan(plan.planid)}
                              disabled={
                                (user?.plan === PlanTypeEnum.Free &&
                                  plan.planid === PlanTypeEnum.Free) ||
                                (user?.plan === PlanTypeEnum.standard_month &&
                                  (plan.planid === PlanTypeEnum.Free ||
                                    plan.planid === PlanTypeEnum.premium_month)) ||
                                (user?.plan === PlanTypeEnum.premium_month &&
                                  (plan.planid === PlanTypeEnum.Free ||
                                    plan.planid === PlanTypeEnum.standard_month))
                              }
                            >
                              {cancelSubscriptionLoading ? (
                                <>
                                  <span className="spinner-border spinner-border-sm me-2"></span>
                                  Processing...
                                </>)
                                :
                                "Cancel Plan"
                              }
                            </button>
                            :
                            <button
                              className={`btn w-100 ${isCurrent ? "btn-outline-danger" : isPopular
                                ? "btn-primary"
                                : "btn-outline-primary"
                                }`}
                              onClick={() => handleChoosePlan(plan.planid)}
                              disabled={
                                (user?.plan === PlanTypeEnum.Free &&
                                  plan.planid === PlanTypeEnum.Free) ||
                                (user?.plan === PlanTypeEnum.standard_month &&
                                  (plan.planid === PlanTypeEnum.Free ||
                                    plan.planid === PlanTypeEnum.premium_month)) ||
                                (user?.plan === PlanTypeEnum.premium_month &&
                                  (plan.planid === PlanTypeEnum.Free ||
                                    plan.planid === PlanTypeEnum.standard_month))
                              }
                            >
                              {parseFloat(plan.price) === 0
                                ? "Switch to Free"
                                : "Upgrade"}
                            </button>
                          }
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}

            {selectedPlan && (
              <div className="row justify-content-center py-2">
                <div className="col-md-8">
                  <div className="d-flex align-items-center justify-content-between p-3 mb-3 bg-light rounded-3">
                    <div>
                      <div className="fw-semibold">{selectedPlanDef?.name} plan</div>
                      <div className="text-muted small">Billed monthly, cancel any time</div>
                    </div>
                    <div className="fs-4 fw-bold">${selectedPlanDef?.price}/mo</div>
                  </div>

                  {clientTokenLoading && (
                    <div className="text-center py-5">
                      <div className="spinner-border text-primary" role="status" />
                      <p className="text-muted mt-3">Loading secure payment form...</p>
                    </div>
                  )}

                  {clientToken && (
                    <>
                      <DropIn
                        options={{ authorization: clientToken }}
                        onInstance={(instance) => setDropinInstance(instance)}
                      />
                      <div className="d-flex gap-2 mt-3">
                        <button className="btn btn-outline-secondary" onClick={() => setSelectedPlan(null)}>
                          Back
                        </button>
                        <button
                          className="btn btn-primary flex-grow-1"
                          onClick={handlePay}
                          disabled={checkoutLoading || !dropinInstance}
                        >
                          {checkoutLoading ? (
                            <>
                              <span className="spinner-border spinner-border-sm me-2"></span>
                              Processing...
                            </>
                          ) : (
                            `Pay $${selectedPlanDef?.price} & Upgrade`
                          )}
                        </button>
                      </div>
                      <p className="text-muted small text-center mt-3 mb-0">
                        <i className="bi bi-shield-lock me-1"></i>
                        Sandbox mode — use test card 4111 1111 1111 1111, any future expiry, any CVV.
                      </p>
                    </>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default SubscriptionModal;
