import React, { useEffect, useState } from "react";
import { Link as RouterLink } from "react-router-dom";
import { toast } from "react-toastify";
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { useUpgradeModal } from "../components/DashboardLayout";
import StatCard from "../components/StatCard";
import { API_BASE, DateFormate, PlanTypeEnum } from "../constant/constant";
import Messeges from "../constant/Messeges";
import { createLink, fetchLinks, fetchStats } from "../store/slices/linkSlice";
import { useAppDispatch, useAppSelector } from "../store/store";
import Moment from "moment";

const Dashboard: React.FC = () => {
  const dispatch = useAppDispatch();
  const { openUpgradeModal } = useUpgradeModal();
  const { stats, statsLoading, links, loading } = useAppSelector((state) => state.links);
  const { user } = useAppSelector((state) => state.auth);

  const [originalUrl, setOriginalUrl] = useState<string>("");

  useEffect(() => {
    dispatch(fetchStats());
    dispatch(fetchLinks());
  }, [dispatch]);

  const handleQuickCreate = (e: React.FormEvent) => {
    e.preventDefault();
    dispatch(createLink({ originalUrl })).then((res: any) => {
      if (!res.error) {
        setOriginalUrl("");
        toast.success(Messeges.m_link_created);
        dispatch(fetchStats());
      }
      else if (res?.payload?.statuscode === 403) {
        toast.error(res.payload);
        openUpgradeModal();
      }
      else if (res?.payload?.statuscode === 409) {
        toast.error(Messeges.m_sort_code_exists);
      }
      else if (res?.payload?.statuscode === 400) {
        toast.error(res?.payload?.message || Messeges.m_createlink);
      }
      else {
        toast.error(Messeges.m_createlink);
      }
    });
  };

  const formattedSeries =
    stats?.series.map((point) => ({
      ...point,
      label: new Date(point.date).toLocaleDateString(undefined, { month: "short", day: "numeric" }),
    })) || [];

  return (
    <div>
      <div className="d-flex flex-wrap align-items-center justify-content-between mb-4 gap-2">
        <div>
          <h3 className="fw-bold mb-1">Welcome back, {user?.name?.split(" ")[0]} 👋</h3>
          <p className="text-muted mb-0">Here's what's happening with your links today.</p>
        </div>
        <RouterLink to="/dashboard/links" className="btn btn-primary">
          <i className="bi bi-plus-lg me-1"></i> Manage links
        </RouterLink>
      </div>

      {/* Quick create */}
      <div className="card border-0 shadow-sm rounded-4-custom mb-4">
        <div className="card-body p-4">
          <form onSubmit={handleQuickCreate} className="row g-2 align-items-end">
            <div className="col-md-9">
              <label className="form-label small fw-semibold">Quick shorten a link</label>
              <input
                type="url"
                className="form-control form-control-lg"
                placeholder="https://example.com/your-long-link"
                value={originalUrl}
                onChange={(e) => setOriginalUrl(e.target.value)}
                required
              />
            </div>
            <div className="col-md-3">
              <button className="btn btn-primary btn-lg w-100" type="submit" disabled={loading}>
                {loading ? "Creating..." : "Shorten"}
              </button>
            </div>
          </form>
        </div>
      </div>

      {/* Stat cards */}
      <div className="row g-3 mb-4">
        <div className="col-sm-6 col-lg-3">
          <StatCard icon="bi-link-45deg" label="Total links" value={stats?.totalLinks ?? "—"} accent="primary" />
        </div>
        <div className="col-sm-6 col-lg-3">
          <StatCard icon="bi-cursor-fill" label="Total clicks" value={stats?.totalClicks ?? "—"} accent="success" />
        </div>
        <div className="col-sm-6 col-lg-3">
          <StatCard
            icon="bi-graph-up"
            label="Clicks (14d)"
            value={formattedSeries.reduce((sum, p) => sum + p.clicks, 0)}
            accent="info"
          />
        </div>
        <div className="col-sm-6 col-lg-3">
          <StatCard
            icon="bi-star-fill"
            label="Current plan"
            value={user?.plan ? user.plan[0].toUpperCase() + user.plan.slice(1) : PlanTypeEnum.Free}
            accent="warning"
            subtext={user?.plan !== PlanTypeEnum.premium_month ? "Tap sidebar to upgrade" : "All features unlocked"}
          />
        </div>
      </div>

      <div className="row g-4">
        {/* Chart */}
        <div className="col-lg-8">
          <div className="card border-0 shadow-sm rounded-4-custom h-100">
            <div className="card-body p-4">
              <h6 className="fw-bold mb-3">Clicks over the last 14 days</h6>
              {statsLoading ? (
                <div className="text-center py-5">
                  <div className="spinner-border text-primary" role="status" />
                </div>
              ) : (
                <ResponsiveContainer width="100%" height={280}>
                  <AreaChart data={formattedSeries}>
                    <defs>
                      <linearGradient id="dashColor" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#0d6efd" stopOpacity={0.35} />
                        <stop offset="95%" stopColor="#0d6efd" stopOpacity={0} />
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="label" tick={{ fontSize: 12 }} />
                    <YAxis allowDecimals={false} tick={{ fontSize: 12 }} width={30} />
                    <Tooltip />
                    <Area
                      type="monotone"
                      dataKey="clicks"
                      stroke="#0d6efd"
                      strokeWidth={2}
                      fill="url(#dashColor)"
                    />
                  </AreaChart>
                </ResponsiveContainer>
              )}
            </div>
          </div>
        </div>

        {/* Top links */}
        <div className="col-lg-4">
          <div className="card border-0 shadow-sm rounded-4-custom h-100">
            <div className="card-body p-4">
              <h6 className="fw-bold mb-3">Top performing links</h6>
              {!stats?.topLinks?.length ? (
                <p className="text-muted small mb-0">No clicks yet — share a link to see it here.</p>
              ) : (
                <ul className="list-unstyled mb-0">
                  {stats.topLinks.map((link) => (
                    <li
                      key={link._id}
                      className="d-flex justify-content-between align-items-center py-2 border-bottom"
                    >
                      <div className="text-truncate me-2" style={{ maxWidth: 180 }}>
                        <div className="small fw-semibold">/r/{link.shortCode}</div>
                        <div className="text-muted text-truncate" style={{ fontSize: 11 }}>
                          {link.originalUrl}
                        </div>
                      </div>
                      <span className="badge bg-primary rounded-pill">{link.clicks}</span>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Recent links preview */}
      <div className="card border-0 shadow-sm rounded-4-custom mt-4">
        <div className="card-body p-4">
          <div className="d-flex justify-content-between align-items-center mb-3">
            <h6 className="fw-bold mb-0">Recent links</h6>
            <RouterLink to="/dashboard/links" className="small">
              View all <i className="bi bi-arrow-right"></i>
            </RouterLink>
          </div>
          {links.length === 0 ? (
            <p className="text-muted small mb-0">You haven't created any short links yet.</p>
          ) : (
            <div className="table-responsive">
              <table className="table table-fixed table-col4 align-middle mb-0">
                <thead>
                  <tr className="text-muted small">
                    <th>Short link</th>
                    <th>Destination</th>
                    <th>Expire At</th>
                    <th className="text-center">Clicks</th>
                  </tr>
                </thead>
                <tbody>
                  {links.slice(0, 5).map((link) => (
                    <tr key={link._id}>
                      <td>
                        <a href={`${API_BASE}/r/${link.shortCode}`} target="_blank" rel="noopener noreferrer">
                          /r/{link.shortCode}
                        </a>
                      </td>
                      <td className="text-truncate">
                        {link.originalUrl}
                      </td>
                      <td className="text-truncate">
                        {link.expiresAt ? Moment.utc(link.expiresAt).format(DateFormate.YYYYMMMDDDash) : "-"}
                      </td>
                      <td className="text-center">
                        <span className="badge bg-secondary">{link.clicks}</span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
