import React from "react";

interface StatCardProps {
  icon: string;
  label: string;
  value: string | number;
  accent?: "primary" | "success" | "warning" | "info";
  subtext?: string;
}

const StatCard: React.FC<StatCardProps> = ({ icon, label, value, accent = "primary", subtext }) => {
  return (
    <div className="card border-0 shadow-sm h-100" style={{ borderRadius: 14 }}>
      <div className="card-body p-4 d-flex align-items-center gap-3">
        <div
          className={`d-flex align-items-center justify-content-center rounded-3 bg-${accent} bg-opacity-10 text-${accent}`}
          style={{ width: 52, height: 52, flexShrink: 0 }}
        >
          <i className={`bi ${icon} fs-4`}></i>
        </div>
        <div>
          <div className="text-muted small">{label}</div>
          <div className="fs-3 fw-bold lh-1 info-cardtext">{value}</div>
          {subtext && <div className="text-muted small mt-1">{subtext}</div>}
        </div>
      </div>
    </div>
  );
};

export default StatCard;
